 schema=[{'@context':'https://schema.org','@type':'WebPage','name':d['h1'],'description':d['desc'],'url':url,'inLanguage':LANG[i],'about':{'@type':'Service','name':d['h1'],'provider':{'@type':'Organization','name':'Mujitech','url':'https://mujitech.ch/'}}},{'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':d['breadcrumb'],'item':'https://mujitech.ch'+pref+'privatkunden.html'},{'@type':'ListItem','position':2,'name':d['h1'],'item':url}]}]
 t=re.sub(r'<script type="application/ld\+json">.*?</script>','<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False)+'</script>',t,count=1,flags=re.S)
 cta=pref+'privatkunden.html?service=PC-%2FLaptop-Optimierung#service-anfrage'
 main='<main class="repair-guide-main" id="main"><nav class="guide-breadcrumb"><a href="'+pref+'privatkunden.html">'+e(d['breadcrumb'])+'</a> / '+e(d['h1'])+'</nav><h1>'+e(d['h1'])+'</h1><p class="guide-lead">'+e(d['lead'])+'</p><p><a class="service-search-cta" href="'+cta+'">'+e(d['ask'])+'</a></p>'
