 main+='</section><p><a href="'+pref+'unternehmen.html">'+e(d['business'])+'</a></p><p><a class="service-search-cta" href="'+cta+'">'+e(d['ask'])+'</a></p><aside><p>'+e(d['note'])+' <a href="'+SOURCE+'" target="_blank" rel="noopener noreferrer">'+e(d['source'])+'</a></p></aside></main>'
 t=re.sub(r'<main\b.*?</main>',main,t,count=1,flags=re.S);(ROOT/FILES[i]).write_text(t)
